// Des: Tests for ru-page-prob and ru-labl-cana: redaction, fixture replay, live canary on the sim in vi, en, drift B, drift C
// Flo: redact names > dump sim page > replay offline > run canary live > assert missing keys
// I/O: names, json, sim pages > pass or fail
// Run: zig build test
// ===================================================================
const std = @import("std"); const prob = @import("ru-page-prob.zig"); const lab = @import("cf-labl-load.zig"); const fnd = @import("ru-labl-find.zig"); const snap = @import("ru-page-snap.zig"); const mock = @import("te-mock-page.zig"); const zsim = @import("te-zsim-page.zig"); const sess = @import("ru-sess-ctxz.zig"); const cana = @import("ru-labl-cana.zig"); const data = @import("st-stat-data.zig"); const conf = @import("cf-conf-load.zig"); const T = std.testing;
const FIX = @embedFile("so-fixt-chat.json");
fn profOf(tmpz: *std.testing.TmpDir, buff: []u8) ![]const u8 { return std.fmt.bufPrint(buff, ".zig-cache/tmp/{s}/prof", .{tmpz.sub_path}); }
test "token is stable, hides the text and keeps the length" { var aren = std.heap.ArenaAllocator.init(T.allocator); defer aren.deinit(); const one = try prob.token(aren.allocator(), "secret message"); const two = try prob.token(aren.allocator(), "secret message"); try T.expectEqualStrings(one, two); try T.expect(std.mem.find(u8, one, "secret") == null); try T.expect(std.mem.endsWith(u8, one, ":14»")); try T.expect(!std.mem.eql(u8, one, try prob.token(aren.allocator(), "secret messagf"))); }
test "redact keeps exact labels, hashes prefixed names and everything else" { var aren = std.heap.ArenaAllocator.init(T.allocator); defer aren.deinit(); const alo = aren.allocator(); const reg = try lab.builtin(alo); try T.expectEqualStrings("Gửi", try prob.redactName(alo, &reg, "Gửi")); try T.expectEqualStrings("send", try prob.redactName(alo, &reg, "send")); const pre = try prob.redactName(alo, &reg, "Đồng ý Lan"); try T.expect(std.mem.startsWith(u8, pre, "Đồng ý «h:")); try T.expect(std.mem.find(u8, pre, "Lan") == null); const msg = try prob.redactName(alo, &reg, "Gửi ảnh cho Lan nhé"); try T.expect(std.mem.startsWith(u8, msg, "Gửi «h:") or std.mem.startsWith(u8, msg, "«h:")); try T.expect(std.mem.find(u8, msg, "Lan") == null); try T.expectEqualStrings("", try prob.redactName(alo, &reg, "")); }
test "static fixture replays offline: send job labels are all present" { var aren = std.heap.ArenaAllocator.init(T.allocator); defer aren.deinit(); const alo = aren.allocator(); const reg = try lab.builtin(alo); const nodes = try prob.fromFixture(alo, FIX); try T.expectEqual(@as(usize, 10), nodes.len); const jk = reg.jobKeys("send").?; try T.expectEqual(@as(usize, 0), (try fnd.missingKeys(alo, &reg, nodes, jk.rest)).len); try T.expectEqual(@as(usize, 0), (try fnd.missingKeys(alo, &reg, nodes, jk.chat)).len); const need = [_][]const u8{ "send_butt", "frie_butt" }; const miss = try fnd.missingKeys(alo, &reg, nodes, &need); try T.expectEqual(@as(usize, 1), miss.len); try T.expectEqualStrings("frie_butt", miss[0]); try T.expectError(error.BadConfig, prob.fromFixture(alo, "{bad")); try T.expectError(error.BadConfig, prob.fromFixture(alo, "[]")); }
test "live dump of the sim holds no raw chat text and replays with every label found, vi and en" { var tmpz = std.testing.tmpDir(.{}); defer tmpz.cleanup(); var buff: [160]u8 = undefined; var aren = std.heap.ArenaAllocator.init(T.allocator); defer aren.deinit(); const alo = aren.allocator(); const page = try zsim.html(alo); var mok = try mock.start(T.allocator, T.io, try profOf(&tmpz, &buff), page); defer mok.stop(); const reg = try lab.builtin(alo); for ([_][]const u8{ "vi", "en" }) |lng| { const js = try std.fmt.allocPrint(alo, "Z.set('lang','{s}');openChat(Z.chats[0]);'x'", .{lng}); _ = try snap.evalStr(alo, mok.conn, js); const nodes = try snap.axSnap(alo, mok.conn); const text = try snap.pageText(alo, mok.conn); const body = try prob.dump(alo, &reg, nodes, text, 5); try T.expect(std.mem.find(u8, body, "Dinner") == null); try T.expect(std.mem.find(u8, body, "Hi son") == null); try T.expect(std.mem.find(u8, body, "Contact 00") == null); const back = try prob.fromFixture(alo, body); var it = reg.jobs.map.iterator(); while (it.next()) |ent| { try T.expectEqual(@as(usize, 0), (try fnd.missingKeys(alo, &reg, back, ent.value_ptr.rest)).len); try T.expectEqual(@as(usize, 0), (try fnd.missingKeys(alo, &reg, back, ent.value_ptr.chat)).len); } } }
test "live canary: ok in vi, en and alternate names (drift B); drift C is reported per job" { var tmpz = std.testing.tmpDir(.{}); defer tmpz.cleanup(); var buff: [160]u8 = undefined; var aren = std.heap.ArenaAllocator.init(T.allocator); defer aren.deinit(); const alo = aren.allocator(); const page = try zsim.html(alo); var mok = try mock.start(T.allocator, T.io, try profOf(&tmpz, &buff), page); defer mok.stop(); var sto = try data.Stor.open(T.allocator, ":memory:"); defer sto.close(); var cfg: conf.Conf = .{}; cfg.warm_dayz_coun = 0; var ses = sess.Sess.init(T.allocator, T.io, alo, cfg, &sto, mok.conn, .read); ses.fast = true; ses.fake_ms = 100 * 86400000 + 12 * 3600000; ses.job = "canary"; const jobs = ses.reg.jobs.map.count(); for ([_][]const u8{ "Z.set('lang','vi')", "Z.set('lang','en')", "Z.set('drift','B')" }) |js| { _ = try snap.evalStr(alo, mok.conn, js); const rep = try cana.run(&ses, ""); try T.expectEqual(@as(u32, @intCast(jobs)), rep.prev); try T.expectEqual(@as(u32, 0), rep.skip); } _ = try snap.evalStr(alo, mok.conn, "Z.set('drift','C')"); const bad = try cana.run(&ses, ""); try T.expect(bad.skip > 0); var found = false; for (bad.lines) |ln| { if (std.mem.startsWith(u8, ln, "MISSING send:") and std.mem.find(u8, ln, "send_butt") != null) found = true; } try T.expect(found); const one = try cana.run(&ses, "send"); try T.expectEqual(@as(u32, 1), one.skip); try T.expectError(error.BadJob, cana.run(&ses, "nojob")); }
